'use strict';
(()=>{
 const menu=document.querySelector('#menu-toggle'),nav=document.querySelector('#navigation');
 if(!document.querySelector('#appointment-form')&&menu){menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}});}
 const search=document.querySelector('#content-search'),filter=document.querySelector('#content-filter');
 function searchContent(){let count=0;document.querySelectorAll('.filterable').forEach(card=>{card.hidden=!(card.textContent.toLowerCase().includes(search.value.toLowerCase().trim())&&(!filter.value||card.dataset.category===filter.value));if(!card.hidden)count++;});document.querySelector('#search-status').textContent=count?`${count} result${count===1?'':'s'}`:'No matches. Try another topic or area.';}
 if(search){search.addEventListener('input',searchContent);filter.addEventListener('change',searchContent);searchContent();}
 document.querySelectorAll('[data-share]').forEach(container=>{
  const canonical=document.querySelector('link[rel=canonical]')?.href||'https://healthyconceptmedical.com/';
  const title=document.title.replace(' | Healthy Concept Medical Centre','');
  function tracked(source){let u=new URL(canonical);u.searchParams.set('utm_source',source);u.searchParams.set('utm_medium','social');return u.href;}
  const links=[['WhatsApp','https://wa.me/?text='+encodeURIComponent(title+' — '+tracked('whatsapp'))],['Facebook','https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(tracked('facebook'))],['LinkedIn','https://www.linkedin.com/sharing/share-offsite/?url='+encodeURIComponent(tracked('linkedin'))]];
  for(const [label,url] of links){let a=document.createElement('a');a.textContent=label+' ↗';a.href=url;a.target='_blank';a.rel='noopener noreferrer';container.append(a);}
  const status=container.parentElement.querySelector('.share-status');
  for(const [label,text] of [['Copy link',canonical],['Copy social post',`${title}\nHealthy Concept Medical Centre, 58 Barnett Street, Montego Bay. General doctor consultations from JA$3,000. Call +1 876 669 5974.\n${tracked('social_profile')}`]]){let b=document.createElement('button');b.textContent=label;b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);status.textContent='Copied. You can now paste it into your post or profile.';}catch{status.textContent='Copy this address: '+canonical;}});container.append(b);}
 });

 const socialProfiles=(window.HCMC_SOCIAL_PROFILES||[]).filter(profile=>{try{const u=new URL(profile.url);return u.protocol==='https:'&&['facebook.com','www.facebook.com','instagram.com','www.instagram.com','linkedin.com','www.linkedin.com','youtube.com','www.youtube.com','tiktok.com','www.tiktok.com'].includes(u.hostname)&&typeof profile.label==='string';}catch{return false;}});
 if(socialProfiles.length){const follow=document.createElement('div');follow.className='wrap share-links';follow.setAttribute('aria-label','Follow Healthy Concept');for(const profile of socialProfiles){const a=document.createElement('a');a.href=profile.url;a.textContent='Follow us on '+profile.label;a.target='_blank';a.rel='noopener noreferrer';follow.append(a);}document.querySelector('footer').prepend(follow);}
 const news=document.querySelector('#news-grid');
 async function refreshNews(){const status=document.querySelector('#news-status'),button=document.querySelector('#refresh-news');button.disabled=true;
 try{const api=window.HCMC_CONFIG?.apiBase;if(!api)throw new Error();const r=await fetch(api+'/api/news',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw new Error();const data=await r.json();if(!Array.isArray(data.items)||!data.items.length)throw new Error();const cards=[];for(const item of data.items){const u=new URL(item.url);if(u.protocol!=='https:'||!['moh.gov.jm','www.moh.gov.jm'].includes(u.hostname))continue;const card=document.createElement('article');card.className='hub-card';const p=document.createElement('p');p.className='eyebrow';p.textContent='MINISTRY OF HEALTH & WELLNESS';const date=document.createElement('time');date.textContent=item.date?new Date(item.date).toLocaleDateString('en-GB',{timeZone:'UTC',day:'numeric',month:'long',year:'numeric'}):'See source for date';const h=document.createElement('h2'),a=document.createElement('a');a.href=u.href;a.textContent=item.title;a.target='_blank';a.rel='noopener noreferrer';h.append(a);card.append(p,date,h);cards.push(card);}if(!cards.length)throw new Error();news.replaceChildren(...cards);status.textContent=data.live?'Official feed · last fetched '+new Date(data.fetchedAt).toLocaleString('en-GB',{timeZone:'America/Jamaica'})+' (Jamaica time)':'Live feed unavailable. Showing selected official updates checked 21 October 2026.';}catch{status.textContent='Live feed unavailable. Showing selected official updates checked 21 October 2026.';}finally{button.disabled=false;}}
 if(news){document.querySelector('#refresh-news').addEventListener('click',refreshNews);refreshNews();}
})();
